//
// This is only a SKELETON file for the 'Forth' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const NUMBER_RE = /^-?\d+$/;

const pop = (stack) => {
  if (stack.length === 0) {
    throw new Error('Stack empty');
  }
  return stack.pop();
};

const BUILTINS = {
  '+': (s) => s.push(pop(s) + pop(s)),
  '-': (s) => s.push(pop(s) - pop(s)),
  '*': (s) => s.push(pop(s) * pop(s)),
  '/': (s) => {
    const divisor = pop(s);
    if (divisor === 0) {
      throw new Error('Division by zero');
    }
    const dividend = pop(s);
    s.push(Math.trunc(dividend / divisor));
  },
  dup: (s) => s.push(pop(s)),
  drop: (s) => pop(s),
  swap: (s) => {
    const a = pop(s);
    const b = pop(s);
    s.push(a, b);
  },
  over: (s) => {
    const a = pop(s);
    const b = pop(s);
    s.push(b, a, b);
  },
};

export class Forth {
  constructor() {
    this._stack = [];
